def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    def get_score(grid):
        score = 0
        for row in grid:
            for cell in row:
                score += cell
        return score

    def check_winner(grid):
        # Check for three in a row horizontally
        for row in grid:
            if sum(row) == 3 and all(cell == player_color for cell, player_color in zip(row, ['R', 'B'])):
                return player_color

        # Check for three in a row vertically
        for col in range(3):
            if sum(grid[row][col] for row in range(3)) == 3 and all(cell == player_color for cell, player_color in zip(grid[0][col], ['R', 'B'])):
                return player_color

        # Check for three in a row diagonally (top-left to bottom-right)
        if sum(grid[i][i] for i in range(3)) == 3:
            return 'R'
        if sum(grid[i][2-i] for i in range(3)) == 3:
            return 'B'

        # If no one has won, return the player with the higher total score
        takashi_score = get_score(grid[:3])
        aoki_score = get_score(grid[3:])
        if takashi_score > aoki_score:
            return 'Takahashi'
        else:
            return 'Aoki'

    # Determine the starting player (even indexed rows start with 'B')
    start_player = 'B' if sum([1 for row in grid if row[0] % 2 == 0]) % 2 == 0 else 'Takahashi'

    # Initialize scores
    takashi_score = 0
    aoki_score = 0

    # Simulate the game
    for i in range(3):
        # Find the next white cell for the current player
        for j in range(3):
            if grid[i][j] == 0:
                grid[i][j] = start_player
                takashi_score += grid[i][j]
                if check_winner(grid) == start_player:
                    return start_player
                grid[i][j] = 0
                aoki_score += grid[i][j]
        if check_winner(grid) == start_player:
            return start_player

    # If all cells are painted, the player with the higher total score wins
    return 'Aoki' if aoki_score > takashi_score else 'Takahashi'
