def count_good_strings(n: int, k: int, s: str) -> int:
    def check_substring(s: str, start: int, end: int) -> bool:
        """Helper function to check if a substring from start to end is a palindrome"""
        if end < start:
            return False
        if end == start:
            return s[start] == s[end]
        return check_substring(s, start + 1, end - 1)

    def is_good_string(s: str) -> bool:
        """Helper function to determine if a string is good (no palindromic substring of length k)"""
        for i in range(n):
            for j in range(i + 1, n + 1):
                if check_substring(s, i, j - 1):
                    return False
        return True

    def count_good_strings_modulo(n: int, k: int) -> int:
        mod = 998244353
        return sum(1 for _ in range(n) if is_good_string(s[:i] + s[i + 1:])) % mod

    return count_good_strings_modulo(n, k)
