def expected_operations(N: int, M: int) -> int:
    MOD = 998244353
    total_operations = 0

    def next_vertex(v):
        if v >= N * M:
            return 0
        return max(v - N, 0)

    def random_choice(vertices):
        return vertices[random.randint(0, len(vertices) - 1)]

    painted = set()
    vertices = list(range(N * M + 1))
    painted.add(0)

    while len(painted) < N * M:
        v = random_choice(vertices)
        if v not in painted:
            painted.add(v)
            total_operations += 1
            for neighbor in [next_vertex(v)]:
                if neighbor not in painted:
                    total_operations += random_choice(list(neighbor + [v]))
                    painted.add(neighbor)

    return total_operations % MOD

